    // is the world pixel (px, py) walkable? Outside the map counts as blocked.
    inline bool is_walkable(int px, int py)
    {
        if(px < 0 || py < 0 || px >= pixel_w || py >= pixel_h)
        {
            return false;
        }
        return walkable[(py / tile_size) * tiles_w + (px / tile_size)] != 0;
    }
